using System;using System.Collections.Generic;using System.IO;using System.IO.Compression;using System.Linq;using System.Text;using System.Text.RegularExpressions;
namespace PZ3D {
 sealed class ViewpointAddon {public string Key,Id,Title,Description,Warning;public ulong Item;public ViewpointAddon(string key,ulong item,string id,string title,string description,string warning=""){Key=key;Item=item;Id=id;Title=title;Description=description;Warning=warning;}}
 sealed class AddonFiles {public string Folder,Info,Jar;public Dictionary<string,string> Metadata;}
 static class ViewpointAddons {
  public static readonly ViewpointAddon[] All={new ViewpointAddon("shelves",3815931973,"ProjectViewpointShelves","KK 动态货架","按库存显示空、少量和满货架；兼容 6244 模型。"),new ViewpointAddon("surface",3814398576,"ViewpointSurface","Surface Fix · 表面修复","修复墙面、窗户和天花板贴图。"),new ViewpointAddon("door",3812151347,"ViewpointDoor","Door Fix · 门修复","修复门两侧光照、贴图与开关外观。"),new ViewpointAddon("roofs",3814178814,"ViewpointTileFix","Complete Roofs · 完整屋顶","补齐缺失屋顶、山墙与拐角。","多人仍为实验。移除前按作者说明关闭 Complete the roofs 并访问曾加载区域；可能有已保存的标记瓦片。"),new ViewpointAddon("foraging",3814994364,"ViewpointForaging","Viewpoint 搜寻与追踪","3D 搜寻标记、踪迹、搜索范围与拾取提示。","作者未验证多人；更新可能影响标记和雾层。"),new ViewpointAddon("fishing",3814560827,"FishingView","Viewpoint 钓鱼","鱼线、浮漂、视线抛竿与水面鱼点。","作者未验证多人；有自己的水面效果，需核对当前光影。"),new ViewpointAddon("weather",3813908957,"ViewpointTrueWeathers","True Weathers · 天气与光照","仅视觉模块；不安装 Gameplay，不改服务器。","作者可能自动选用专用光影；请在模组选项保留其他光影。服务器共享积雪与玩法需服务端配合，不在本预设中。"),new ViewpointAddon("trees",3813172420,"ProjectViewpointNearVegetation","KK 动态季节树木","3D 树冠、风动、落叶与积雪；先用 Medium 密度。","树林可能增加渲染负担；多人及光影组合需实测。")};
  public static ViewpointAddon Get(string key){var a=All.FirstOrDefault(x=>x.Key==key);if(a==null)throw new Exception("未知可选扩展。");return a;}
  public static Dictionary<string,string> Metadata(string path){LauncherMaintenance.NoReparse(path);if(!File.Exists(path))return new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);if(new FileInfo(path).Length>262144)throw new Exception("模组元数据过大。");var result=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(string line in File.ReadAllLines(path)){int at=line.IndexOf('=');if(at>0)result[line.Substring(0,at).Trim()]=line.Substring(at+1).Trim();}return result;}
  public static AddonFiles Find(Engine e,ViewpointAddon a){return Resolve(e,a,GameVersionProbe.Read(e.Game)??new Version(42,0));}
  internal static AddonFiles Resolve(Engine e,ViewpointAddon a,Version version){string root=Path.Combine(InstallWorkflow.Source(e,a.Item),"mods");LauncherMaintenance.NoReparse(root);if(!Directory.Exists(root))throw new Exception("扩展尚未下载。");Version current=new Version(version.Major,version.Minor,Math.Max(0,version.Build),Math.Max(0,version.Revision));var found=new List<AddonFiles>();foreach(string folder in Directory.GetDirectories(root)){LauncherMaintenance.NoReparse(folder);string common=Path.Combine(folder,"common","mod.info");var meta=Metadata(common);string active=folder;Version best=new Version(0,0,0,0);foreach(string part in Directory.GetDirectories(folder)){LauncherMaintenance.NoReparse(part);Version candidate;if(!Version.TryParse(Path.GetFileName(part).Contains(".")?Path.GetFileName(part):Path.GetFileName(part)+".0",out candidate)||candidate.Major!=42)continue;Version normalized=new Version(candidate.Major,candidate.Minor,Math.Max(0,candidate.Build),Math.Max(0,candidate.Revision));if(normalized<=current&&normalized>best){active=part;best=normalized;}}if(active==folder&&File.Exists(common)&&!File.Exists(Path.Combine(folder,"mod.info")))continue;string activeInfo=Path.Combine(active,"mod.info");if(File.Exists(activeInfo))foreach(var pair in Metadata(activeInfo))meta[pair.Key]=pair.Value;string info=File.Exists(activeInfo)?activeInfo:common;string id;if(!meta.TryGetValue("id",out id)||id!=a.Id)continue;string jar=null,relative;if(meta.TryGetValue("javaJarFile",out relative)){if(Path.IsPathRooted(relative)||relative.Split(new[]{'/','\\'}).Any(x=>x==".."))throw new Exception("Java 扩展路径越界。");foreach(string part in new[]{active,Path.Combine(folder,"common")}.Distinct()){string path=Path.GetFullPath(Path.Combine(part,relative));if(!path.StartsWith(Path.GetFullPath(folder)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("Java 扩展路径越界。");LauncherMaintenance.NoReparse(path);if(File.Exists(path)){jar=path;break;}}if(jar==null||!jar.EndsWith(".jar",StringComparison.OrdinalIgnoreCase)||relative.Replace('\\','/').Contains("/server/"))throw new Exception("客户端 Java 文件缺失或无效。");}found.Add(new AddonFiles{Folder=folder,Info=info,Jar=jar,Metadata=meta});}if(found.Count!=1)throw new Exception("扩展来源缺失或重复，不能确认加载文件。");return found[0];}
  public static bool Enabled(Engine e,ViewpointAddon a){return File.Exists(e.Mods)&&Regex.IsMatch(File.ReadAllText(e.Mods),@"(?m)^\s*mod\s*=\s*"+Regex.Escape(a.Id)+@"\s*,");}
  public static bool Preload(AddonFiles files){if(files.Jar==null)return false;string declared;if(!files.Metadata.TryGetValue("javaPreload",out declared)||!declared.Equals("true",StringComparison.OrdinalIgnoreCase))return false;try{using(var zip=ZipFile.OpenRead(files.Jar)){var entry=zip.GetEntry("META-INF/MANIFEST.MF");if(entry==null||entry.Length>65536)return false;using(var reader=new StreamReader(entry.Open()))return Regex.IsMatch(reader.ReadToEnd(),@"(?im)^ZB-Preload:\s*true\s*$");}}catch{return false;}}
  public static string BuildDefault(string text,string key,bool on){var a=Get(key);var blocks=Regex.Matches(text,@"\bmods\s*\{(?<body>[^}]*)\}");if(blocks.Count!=1)throw new Exception("模组清单格式无法识别。");var block=blocks[0];string old=block.Groups["body"].Value;string body=Regex.Replace(old,@"(?m)^[ \t]*mod\s*=\s*"+Regex.Escape(a.Id)+@"\s*,[^\r\n]*(?:\r?\n|$)","");if(on){if(Regex.IsMatch(old,@"(?m)^\s*mod\s*=\s*"+Regex.Escape(a.Id)+@"\s*,"))return text;string nl=text.Contains("\r\n")?"\r\n":"\n";body=body+"    mod = "+a.Id+","+nl;}return text.Substring(0,block.Groups["body"].Index)+body+text.Substring(block.Groups["body"].Index+old.Length);}
  public static string Switch(Engine e,string key,bool on){string name="Local\\OrangeLaunch-"+DlssInstaller.Hash(Encoding.UTF8.GetBytes(Path.GetFullPath(e.User).ToUpperInvariant()));using(var mutex=new System.Threading.Mutex(false,name)){bool held=false;try{try{held=mutex.WaitOne(0);}catch(System.Threading.AbandonedMutexException){held=true;}if(!held||LaunchProfiles.Pending(e))throw new Exception("其他启动／恢复会话尚未完成，暂不修改扩展。");return SwitchUnlocked(e,key,on);}finally{if(held)mutex.ReleaseMutex();}}}
  static string SwitchUnlocked(Engine e,string key,bool on){e.Guard();var a=Get(key);if(on){if(!ShootClient.BaseReady(e))throw new Exception("请先安装 Viewpoint 与 Buddy。");Find(e,a);}LauncherMaintenance.NoReparse(e.Mods);if(!File.Exists(e.Mods))throw new Exception("本地模组清单尚未生成。");byte[] before=File.ReadAllBytes(e.Mods);string text=new UTF8Encoding(false,true).GetString(before).TrimStart('\uFEFF'),next=BuildDefault(text,key,on);if(next==text)return "扩展状态未改变。";string backup=Path.Combine(e.Data,"backups","addon-"+Guid.NewGuid().ToString("N"));LauncherMaintenance.NoReparse(backup);Directory.CreateDirectory(backup);File.WriteAllBytes(Path.Combine(backup,"default.txt"),before);string temp=e.Mods+".addon-"+Guid.NewGuid().ToString("N");try{File.WriteAllText(temp,next,new UTF8Encoding(false));e.Guard();if(!before.SequenceEqual(File.ReadAllBytes(e.Mods)))throw new Exception("清单在安装期间改变，未覆盖。");File.Replace(temp,e.Mods,null);}finally{if(File.Exists(temp))File.Delete(temp);}return (on?"已配置，下次启动生效；需核对 Java 授权与游戏日志。":"已停用本地清单，下载文件保留。服务器强制加载不由此开关控制。")+"\r\n"+a.Warning;}
 }}
